def compute(vars):
    sales_2018 = vars["v1"]
    sales_2017 = vars["v2"]
    threshold = 200000
    years_exceeding = int(sales_2018 > threshold) + int(sales_2017 > threshold)

    return {
        "value": years_exceeding,
        "trace": {
            "sales_2018": sales_2018,
            "sales_2017": sales_2017,
            "threshold": threshold,
            "years_exceeding": years_exceeding,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "years"
            }
        }
    }
